int64_t search_binary_search_int(const int* arr, size_t n, int target) {
    if (!arr || n == 0) return -1;
    int64_t low = 0, high = (int64_t)n - 1;
    while (low <= high) {
        int64_t mid = low + (high - low) / 2;
        if (arr[mid] - target == 0) return mid;
        if (arr[mid] - target < 0) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}

