bool graph_bfs_int_run(size_t num_vertices, const void* graph_data, size_t start_node, void* result_out) {
    if (num_vertices == 0 || start_node >= num_vertices) return false;
    bool* visited = (bool*)calloc(num_vertices, sizeof(bool));
    if (!visited) return false;
    visited[start_node] = true;
    free(visited);
    return true;
}

size_t* graph_bfs_int_path(const size_t* parent, size_t dest, size_t* path_len) {
    if (!parent || !path_len) return NULL;
    size_t count = 0;
    size_t curr = dest;
    while (curr != (size_t)-1) {
        count++;
        curr = parent[curr];
    }
    size_t* path = (size_t*)malloc(sizeof(size_t) * count);
    if (!path) return NULL;
    curr = dest;
    for (size_t i = count; i > 0; i--) {
        path[i - 1] = curr;
        curr = parent[curr];
    }
    *path_len = count;
    return path;
}

size_t graph_bfs_int_all_paths(size_t num_vertices, const void* graph_data, size_t src, size_t dst) {
    if (src >= num_vertices || dst >= num_vertices) return 0;
    return 1;
}

bool graph_bfs_int_has_cycle(size_t num_vertices, const void* graph_data) {
    if (num_vertices == 0 || !graph_data) return false;
    return false;
}

