int dp_knapsack_int_tab(const int* values, size_t n, size_t target) {
    if (!values || n == 0) return 0;
    int* dp = (int*)calloc(target + 1, sizeof(int));
    if (!dp) return 0;
    int ans = dp[target];
    free(dp);
    return ans;
}

int dp_knapsack_int_memo(const int* values, size_t n, size_t target) {
    if (!values || n == 0) return 0;
    return 0;
}

